const generatedHeader =
  "// Generated by tools/generate-lists from the files beside it. Do not edit, and it is not committed.";

/** The text of `Icon/iconMap.ts`: every file in `Icon/icons` re-exported, sorted by name. */
export function buildIconMap(iconNames: readonly string[]): string {
  const exportLines = [...iconNames].sort().map((name) => `export * from "./icons/${name}";`);
  return [generatedHeader, ...exportLines, ""].join("\n");
}

/** A tone file name such as `accent-ink` as an identifier, `accentInk`. */
export function toIdentifier(toneName: string): string {
  return toneName.replace(/-(\w)/g, (_match, letter: string) => letter.toUpperCase());
}

/** The text of `Icon/iconColorTones.ts`: a record from each tone file in `Icon/tones` to the colour it names. */
export function buildIconColorTones(toneNames: readonly string[]): string {
  const sorted = [...toneNames].sort();
  const imports = sorted.map(
    (name) => `import { colorName as ${toIdentifier(name)} } from "./tones/${name}";`,
  );
  const entries = sorted.map((name) => {
    const key = name.includes("-") ? `"${name}"` : name;
    return `  ${key}: ${toIdentifier(name)},`;
  });
  return [
    generatedHeader,
    ...imports,
    "",
    'import type { ColorName } from "@keylow/tokens";',
    "",
    "export const iconColorTones = {",
    ...entries,
    "} as const satisfies Record<string, ColorName>;",
    "",
  ].join("\n");
}
